'use strict';
const app = document.getElementById('app');
const stage = document.getElementById('stage');
const screens = {discover:'01 · Discover',details:'02 · Challenge details',create:'03 · Create challenge',evidence:'04 · Submit evidence',assessment:'05 · AI assessment',community:'06 · Community',progress:'07 · Personal progress',signin:'08 · Sign in',foundations:'09 · Foundations',components:'10 · Components',feedback:'11 · Feedback & recovery',rules:'12 · Usage & handoff'};
const selector = document.getElementById('screen-select');
selector.innerHTML = Object.entries(screens).map(([k,v])=>`<option value="${k}">${v}</option>`).join('');
let state = {screen:'discover',mobile:false,category:'All actions',query:'',assessment:'supported',likes:[24,18],liked:[false,false],photos:[null,null],photoErrors:['',''],description:'',shared:false,comments:[]};
let toastTimer;
const paths = {
 arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4 10-10"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',camera:'<path d="M3 7h5l2-3h4l2 3h5v14H3Z"/><circle cx="12" cy="14" r="4"/>',leaf:'<path d="M5 20c0-9 5-15 15-15 0 10-5 15-15 15Zm0 0L16 9"/>',users:'<circle cx="9" cy="8" r="3"/><path d="M3 21v-3c0-4 12-4 12 0v3m2-17a3 3 0 0 1 0 6m1 5c4 0 4 3 4 6"/>',chart:'<path d="M4 3v18h17M8 16v-5m5 5V7m5 9V4"/>',plus:'<path d="M12 4v16M4 12h16"/>',heart:'<path d="M20 5c-3-3-6-1-8 1-2-2-5-4-8-1-6 6 8 15 8 15S26 11 20 5Z"/>',comment:'<path d="M3 4h18v13H8l-5 4V4Z"/>',alert:'<path d="m12 3 10 18H2L12 3Zm0 6v5m0 3v.1"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',refresh:'<path d="M20 8a8 8 0 1 0 1 8M20 3v6h-6"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',mail:'<path d="M3 5h18v14H3Z"/><path d="m3 5 9 7 9-7"/>',recycle:'<path d="m12 3 5 8-5-1m5 1 2-4m2 10H10l3-4m-3 4 4 4M3 17l5-9 2 4M8 8H3"/>'
};
function icon(name,size=24){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${paths[name]||paths.leaf}</svg>`}
const logo = `<svg width="42" height="42" viewBox="0 0 42 42" aria-hidden="true"><rect width="42" height="42" rx="13" fill="#245C42"/><path d="M12 13h18L13 29h17" fill="none" stroke="#DCEAA5" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const brand=()=>`<a class="brand" href="#discover" aria-label="Zyvara home">${logo}<span>zyvara</span></a>`;
function art(kind='cleanup'){return `<svg viewBox="0 0 180 130" aria-hidden="true">${kind==='planting'?'<path d="M88 107V46" stroke="#245C42" stroke-width="4"/><path d="M88 75C46 76 43 48 48 32C82 32 89 54 88 75Z" fill="#245C42"/><path d="M88 55C88 26 120 20 132 29C130 53 111 61 88 55Z" fill="#568165"/><path d="M44 110Q90 83 141 110" fill="none" stroke="#245C42" stroke-width="3"/>':kind==='recycling'?'<path d="m89 22 24 39h-18m18 0 10-17M142 87H97l9-17m-9 17 15 15M45 89l22-39 8 15m-8-15-20-1" fill="none" stroke="#245C42" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/>':'<path d="M15 105Q80 45 165 100" fill="none" stroke="#245C42" stroke-width="3"/><path d="M45 100V42m0 30Q15 64 25 43Q48 40 45 72m0-17Q70 53 78 29Q48 25 45 55" fill="#245C42" stroke="#245C42" stroke-width="3"/><rect x="109" y="56" width="26" height="43" rx="4" fill="#F7F8F2" stroke="#245C42" stroke-width="2"/><path d="M109 62h26" stroke="#245C42" stroke-width="2"/>'}</svg>`}
function sprout(){return `<svg class="feature-art" viewBox="0 0 430 260" aria-hidden="true"><g fill="none" stroke="#568165" stroke-width="1.5"><ellipse cx="220" cy="130" rx="190" ry="125"/><ellipse cx="220" cy="130" rx="160" ry="100"/><ellipse cx="220" cy="130" rx="130" ry="75"/><ellipse cx="220" cy="130" rx="100" ry="50"/></g><path d="M212 210V115" stroke="#DCEAA5" stroke-width="7" stroke-linecap="round"/><path d="M212 146C140 150 120 103 138 74C190 75 213 103 212 146Z" fill="#DCEAA5"/><path d="M213 116C215 60 262 38 302 54C300 100 258 126 213 116Z" fill="#9DBF92"/><circle cx="340" cy="196" r="32" fill="#DCEAA5"/><path d="m326 196 10 10 18-20" fill="none" stroke="#172E25" stroke-width="4" stroke-linecap="round"/></svg>`}
const btn=(label,action='',classes='')=>`<button class="btn ${classes}" ${action?`data-action="${action}"`:''}>${label}</button>`;
const linkBtn=(label,route,classes='')=>`<a class="btn ${classes}" href="#${route}">${label}</a>`;
const status=(kind,label)=>`<span class="status ${kind}">${icon(kind==='warning'?'alert':kind==='error'?'close':kind==='info'?'clock':'check',18)}${label}</span>`;
const header=(title,sub,crumb='')=>`<div class="page-heading">${crumb?`<div class="breadcrumb">${crumb}</div>`:''}<h1>${title}</h1>${sub?`<p class="subtitle">${sub}</p>`:''}</div>`;
const note=(h,t)=>`<section><strong>${h}</strong><p class="muted">${t}</p></section>`;
const field=(name,label,value='',helper='',type='text')=>`<div class="field"><label class="label" for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${value}" ${label.includes('*')?'required':''} ${name==='challenge-title'?'maxlength="80"':''} ${helper?`aria-describedby="${name}-help"`:''}><span id="${name}-help" class="helper">${helper}</span></div>`;
const textarea=(name,label,value='',helper='')=>`<div class="field"><label class="label" for="${name}">${label}</label><textarea id="${name}" name="${name}" ${label.includes('*')?'required':''} ${helper?`aria-describedby="${name}-help"`:''}>${value}</textarea><span id="${name}-help" class="helper">${helper}</span></div>`;
function escapeHTML(text){return String(text).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function navigation(){const active=state.screen==='community'?'community':state.screen==='progress'?'progress':'discover';return `<div class="mock-status-bar" aria-hidden="true"><span>9:41</span><div><svg width="16" height="12" viewBox="0 0 16 12"><path d="M1 10V8m4 2V6m4 4V4m4 6V2" stroke="#172E25" stroke-width="2"/></svg><svg width="16" height="12" viewBox="0 0 16 12"><path d="M1 3Q8-2 15 3M4 6q4-3 8 0M7 9h2" fill="none" stroke="#172E25" stroke-width="1.5"/></svg><svg width="24" height="12" viewBox="0 0 24 12"><rect x="1" y="1" width="20" height="10" rx="2" stroke="#172E25" fill="none"/><rect x="3" y="3" width="16" height="6" rx="1" fill="#172E25"/><path d="M23 4v4" stroke="#172E25"/></svg></div></div><nav class="app-nav" aria-label="Main navigation">${brand()}<div class="nav-links">${[['discover','Discover'],['community','Community'],['progress','My progress']].map(([k,n])=>`<a href="#${k}" class="${active===k?'active':''}" ${active===k?'aria-current="page"':''}>${n}</a>`).join('')}</div><div class="nav-actions">${linkBtn('+ Create challenge','create','secondary compact')}<a href="#progress" class="avatar" aria-label="Henry’s profile">HA</a></div></nav>`}
function bottomNavigation(){return `<nav class="bottom-nav" aria-label="Mobile navigation">${[['discover','Discover','leaf'],['community','Community','users'],['create','Create','plus'],['progress','Progress','chart']].map(([k,n,i])=>`<a class="${state.screen===k?'active':''}" href="#${k}">${icon(i,22)}${n}</a>`).join('')}</nav>`}
const challenges=[{title:'Make room for nature',category:'Cleanups',label:'Cleanup',art:'cleanup',time:'20 min',count:32},{title:'Plant a little possibility',category:'Planting',label:'Planting',art:'planting',time:'45 min',count:18},{title:'Give waste a second life',category:'Recycling',label:'Recycling',art:'recycling',time:'15 min',count:46}];
function challengeCard(c){return `<a href="#details" class="challenge-card" aria-label="View ${c.title}"><div class="category-art ${c.art}">${art(c.art)}</div><div class="card-info"><div class="category">${c.label} / Community challenge</div><h2>${c.title}</h2><p class="small muted">${c.time} · 50 points</p><div class="card-footer"><span>${c.count} contributions</span><b>View challenge ↗</b></div></div></a>`}
function filteredCards(){const list=challenges.filter(c=>(state.category==='All actions'||state.category===c.category)&&c.title.toLowerCase().includes(state.query.toLowerCase()));return list.length?list.map(challengeCard).join(''):`<div class="empty-state" style="grid-column:1/-1;">${icon('search',40)}<h2>No challenges found.</h2><p class="muted">Try another search or reset your filters.</p>${btn('Reset filters','reset-filters','secondary')}</div>`}
function discover(){return `<section class="feature"><div class="feature-copy"><div class="eyebrow">This week / One small action</div><h1>A cleaner corner.<br>A better tomorrow.</h1><p>Take 20 minutes to care for a space you love.</p>${linkBtn('Explore challenge '+icon('arrow',20),'details','accent')}</div>${sprout()}</section><div class="section-heading"><div><h2>Find your next good thing.</h2><p class="muted">Community-created challenges. Everyday possibilities.</p></div><span class="note">24 active challenges · Sample data</span></div><div class="filter-bar" aria-label="Challenge filters">${['All actions','Cleanups','Planting','Recycling','Conservation'].map(n=>`<button class="filter ${state.category===n?'active':''}" data-category="${n}" aria-pressed="${state.category===n}">${n}</button>`).join('')}<label class="search">${icon('search',18)}<span class="sr-only">Search challenges</span><input id="challenge-search" placeholder="Search challenges..." value="${escapeHTML(state.query)}"></label></div><div class="cards" id="challenge-cards">${filteredCards()}</div>`}
function missionSteps(){return [['01','Choose your corner','A campus path, park, or street you can safely access.'],['02','Make the change','Collect litter for about 20 minutes. Bring gloves and a bag.'],['03','Document your effort','Upload a clear photo and a short description. A before photo helps.']].map(([n,h,t])=>`<div class="mission-step"><span>${n}</span><div><strong>${h}</strong><p class="muted">${t}</p></div></div>`).join('')}
function details(){return `${header('Make room for nature.','A 20-minute cleanup for a place that means something to you.','Discover / Cleanups / Make room for nature')}<div class="row between"><span class="eyebrow">Cleanup / Community challenge</span><span class="note">Campus Green Club · Ends Oct 18 · Sample challenge</span></div><div class="columns"><div class="wide stack"><div class="mission-art">${art()}<h2>Leave it a little<br>better than you<br>found it.</h2></div><div class="stack" style="gap:12px;"><h2>Your mission</h2><p class="muted">Choose a safe public space and collect visible litter. Separate recyclables where possible, then dispose of everything responsibly. Leave wildlife and hazardous waste undisturbed.</p></div>${missionSteps()}</div><aside class="rail panel"><span class="eyebrow">A little effort goes a long way</span><div class="reward">50 points</div><p class="muted">For a submission whose visible evidence supports the challenge.</p><div class="divider"></div><div class="metric-row"><span>Time needed</span><b>20 minutes</b></div><div class="metric-row"><span>Community contributions</span><b>32</b></div>${linkBtn('Submit evidence '+icon('arrow',20),'evidence','full')}<p class="note">Gemini assesses what is visible in your photos. It cannot independently verify that an activity happened.</p></aside></div>`}
function create(){return `${header('Start something good.','A clear invitation can turn one action into a community habit.','Discover / Create a challenge')}<div class="columns"><form id="create-form" class="wide stack" novalidate>${field('challenge-title','Challenge title *','Make room for nature','Name a specific action. Up to 80 characters.')}${textarea('challenge-description','What should people do? *','Choose a safe public space and collect visible litter for 20 minutes. Separate recyclables, dispose of waste responsibly, and leave the space cleaner than you found it.','Include the activity, what completion looks like, and any safety guidance.')}<div class="form-two"><div class="field"><label class="label" for="category">Category *</label><select id="category" required><option>Cleanup</option><option>Planting</option><option>Recycling</option><option>Conservation</option></select><span class="helper">Choose the category yourself.</span></div>${field('deadline','Deadline (optional)','2026-10-18','Leave blank for an ongoing challenge.','date')}</div>${textarea('challenge-evidence','What evidence should people share? *','One clear photo showing the cleaned area or collected litter, plus a short description. A before photo is helpful but optional.')}<div class="form-actions"><span class="note">* Required fields</span><div class="row">${linkBtn('Cancel','discover','secondary')}<button class="btn" type="submit">Publish challenge ${icon('arrow',20)}</button></div></div></form><aside class="rail panel field-notes"><div class="eyebrow">Field notes / For creators</div><h2>Keep it small.<br>Make it achievable.</h2>${note('Be specific','“Collect litter for 20 minutes” is easier to act on than “Save the planet.”')}${note('Make evidence clear','Ask for photos that show the result, without exposing people’s private information.')}${note('Celebrate effort','Supported contributions earn 50 points. Unclear evidence gets helpful feedback.')}</aside></div>`}
function uploadSlot(i){return `<div class="upload-slot"><label class="label" for="photo-${i}">${i===0?'Result photo *':'Before photo (optional)'}</label><label class="upload-area" for="photo-${i}">${state.photos[i]?`<img src="${state.photos[i]}" alt="Selected ${i===0?'result':'before'} photo"><span class="uploaded-label">Change photo</span>`:`${icon('camera',40)}<strong>Choose photo</strong><span class="note">or drag and drop here</span>`}<input id="photo-${i}" type="file" accept="image/jpeg,image/png,image/webp" data-photo="${i}" aria-describedby="photo-help-${i}"></label><span id="photo-help-${i}" class="helper">${i===0?'Show the outcome or collected materials.':'Help us see the change you made.'}</span>${state.photoErrors[i]?`<span class="photo-error" role="alert">${state.photoErrors[i]}</span>`:''}</div>`}
function evidence(){return `${header('Your effort, in focus.','Show what changed. Tell us what you did.','Make room for nature / Submit evidence')}<div class="columns"><form id="evidence-form" class="wide stack"><div class="upload-grid">${uploadSlot(0)}${uploadSlot(1)}</div><span class="note">JPG, PNG, or WebP · Up to 10 MB per photo</span>${textarea('submission-description','What did you do? *',escapeHTML(state.description),'Be specific. Your description helps put the photos in context.')}<label class="check-row"><input id="share-choice" type="checkbox" ${state.shared?'checked':''}><span>Share my supported contribution with the community</span></label><div class="form-actions"><span class="note">Photos stay private unless you choose to share.</span><button class="btn" id="submit-evidence" type="submit" ${state.photos[0]&&state.description.trim()?'':'disabled'}>Submit for assessment ${icon('arrow',20)}</button></div><div class="note">Design preview: selected files stay in this browser and are never uploaded.</div></form><aside class="rail panel field-notes"><div class="eyebrow">Before you submit</div><h2>Help your action<br>speak for itself.</h2>${note('Make it visible','Use a clear, well-lit photo showing the result, not just a selfie.')}${note('Respect privacy','Avoid faces, addresses, license plates, and other personal details.')}${note('Know what comes next','Gemini compares the visible evidence with the challenge. Unclear evidence gets suggestions, not accusations.')}</aside></div>`}
const outcomes={supported:{title:'A small action. A real step.',label:'Evidence supports completion',kind:'',points:50,feedback:'The submitted evidence is consistent with a cleanup. Visible litter appears collected, and the description explains how the materials were disposed of.',observations:[['The result is visible','The example submission shows collected materials in the selected space.'],['Your description adds context','The described activity aligns with the community challenge.']],action:'View my progress',route:'progress'},insufficient:{title:'A little more context will help.',label:'Needs more evidence',kind:'warning',points:0,feedback:'The photo is too close to show the surrounding area. We cannot confidently compare the visible result with the challenge requirements.',observations:[['Show a wider view','Include the cleaned area and the collected materials in a clear photo.'],['Keep your description','Your text is saved. Add or replace a photo, then submit again.']],action:'Improve my evidence',route:'evidence'},unsupported:{title:'This evidence does not match yet.',label:'Evidence does not support completion',kind:'error',points:0,feedback:'The visible content does not show the cleanup described in this challenge. This assessment refers to the submitted evidence, not your intentions.',observations:[['Review the challenge','This challenge asks for a photo showing a cleanup result or collected litter.'],['Try another photo','Choose a photo that shows your completed action and submit it again.']],action:'Review and resubmit',route:'evidence'}};
function assessment(){const o=outcomes[state.assessment];return `${header(o.title,'Your contribution / Make room for nature','Submission / AI assessment')}<div class="assessment-tabs" aria-label="Preview assessment outcomes">${[['supported','Supported'],['insufficient','Needs evidence'],['unsupported','Not supported']].map(([k,n])=>`<button class="filter ${state.assessment===k?'active':''}" data-outcome="${k}" aria-pressed="${state.assessment===k}">${n}</button>`).join('')}<span class="note" style="align-self:center;">Illustrative assessment · Sample data</span></div><div class="columns"><div class="wide stack"><div class="assessment-panel">${status(o.kind,o.label)}<div class="reward">${o.points>0?'+':''}${o.points} <span style="font-size:28px;letter-spacing:-.02em;">points</span></div><h2>${o.points?'A good thing, documented.':'Keep going. Your effort matters.'}</h2><p class="muted">${o.feedback}</p><div class="row">${linkBtn(o.action+' '+icon('arrow',20),o.route)}${o.points?btn('Share contribution','share','secondary'):''}</div></div><div class="stack"><h2>What the evidence tells us</h2>${o.observations.map(([h,t])=>`<div class="observation">${icon(o.kind==='warning'?'info':'check',24)}<div><strong>${h}</strong><p class="muted">${t}</p></div></div>`).join('')}</div><div class="feedback-note">AI assessment evaluates visible evidence against the challenge. Photographs alone cannot prove that an activity occurred. Points are awarded by Zyvara’s rules, once per supported contribution.</div></div><aside class="rail panel"><div class="eyebrow">Your submission</div><h3>Make room for nature</h3><div class="sample-evidence">${state.photos[0]?`<img src="${state.photos[0]}" alt="Your selected result photo" style="width:100%;height:100%;object-fit:cover;">`:art()}<span class="caption">${state.photos[0]?'Local photo preview':'Example image placeholder'}</span></div><p class="small muted">${state.description?escapeHTML(state.description):'I cleaned a campus path for 20 minutes and separated the recyclables from the remaining waste.'}</p><div class="divider"></div><div class="metric-row"><span>Assessment</span><b>Gemini-assisted</b></div><div class="metric-row"><span>Confidence</span><b>Medium</b></div><p class="note">Confidence describes the evidence assessment; it is not a certainty score about real-world behavior.</p></aside></div>`}
function post(i,name,initials,title,copy,kind){return `<article class="post"><div class="post-header"><div class="avatar ${i?'secondary':''}">${initials}</div><div class="post-author"><strong>${name}</strong><span class="note">Campus Green Club · ${i?'4':'2'} hours ago</span></div><span class="badge">${title}</span></div><p class="post-copy">${copy}</p><div class="post-visual">${art(kind)}<h2>${i?'A little green.<br>A lot of possibility.':'20 minutes.<br>A cleaner corner.'}</h2></div><div class="post-footer"><button data-like="${i}" class="${state.liked[i]?'liked':''}" aria-pressed="${state.liked[i]}">${icon('heart',20)}<span>${state.likes[i]} encouragements</span></button><button data-comment="${i}">${icon('comment',20)}Comment</button>${status('','Supported contribution')}</div>${state.comments.filter(c=>c.post===i).map(c=>`<p class="comment"><strong>You:</strong> ${escapeHTML(c.text)}</p>`).join('')}<div id="comment-${i}" hidden></div></article>`}
function community(){return `${header('Good things grow together.','Small wins, shared stories, and a community that keeps showing up.')}<div class="row between"><div class="row"><span class="filter active">Latest contributions</span><span class="note">Sample community activity</span></div>${linkBtn('Find an action','discover','secondary')}</div><div class="columns"><div class="wide feed">${post(0,'Amara N.','AN','Cleanup','A few classmates joined me to clean the path behind our library. Two bags of litter later, it already feels more welcoming.','cleanup')}${post(1,'Eli M.','EM','Planting','Started a small native planting patch with our environmental club. Looking forward to watching it grow.','planting')}</div><aside class="rail stack"><div class="panel field-notes"><div class="eyebrow">Community field notes</div><h2>Momentum is<br>made together.</h2><p class="muted">Encourage the effort. Ask thoughtful questions. Share what you learned.</p>${linkBtn('Create a challenge','create','full')}</div><div class="panel"><h3>People making a difference</h3>${[['AN','Amara N.','12 contributions'],['EM','Eli M.','8 contributions'],['SC','Sofia C.','6 contributions']].map(([a,n,t])=>`<div class="community-member"><div class="avatar">${a}</div><div><strong>${n}</strong><div class="note">${t}</div></div>${icon('leaf',20)}</div>`).join('')}<p class="note">Featured members · Example profiles</p></div></aside></div>`}
function progress(){return `${header('Your impact starts here.','Every documented action is another reason to keep going.')}<div class="progress-profile"><div class="avatar">HA</div><div><h2>Henry A.</h2><p class="muted">Campus Green Club · Joined October 2026</p></div><span class="badge">Growing contributor</span></div><div class="stats">${[['250','Points earned'],['5','Supported contributions'],['3','Challenge categories']].map(([n,l])=>`<div class="stat"><strong>${n}</strong><span class="muted">${l}</span></div>`).join('')}</div><div class="columns"><div class="wide stack"><div class="section-heading"><h2>Your action journal</h2><span class="note">Sample activity history</span></div>${[['Make room for nature','Cleanup','Oct 11','+50','Supported'],['Give waste a second life','Recycling','Oct 9','+50','Supported'],['Plant a little possibility','Planting','Oct 7','0','Needs evidence']].map(([h,c,d,p,s])=>`<a class="activity-row" href="#assessment"><div class="activity-icon">${icon(c==='Recycling'?'recycle':'leaf',24)}</div><div class="info"><strong>${h}</strong><div class="note">${c}</div></div><div class="date">${d}</div>${status(s==='Supported'?'':'warning',s)}<div class="points">${p} pts</div></a>`).join('')}</div><aside class="rail stack"><div class="panel"><div class="eyebrow">Activity / Past 4 weeks</div><h3>A little more, each week.</h3><div class="progress-chart" role="img" aria-label="Sample supported contributions by week: 0, 1, 1, 3">${[4,50,50,150].map(n=>`<div style="height:${n}px;"></div>`).join('')}</div><div class="chart-labels"><span>Sep 21</span><span>Sep 28</span><span>Oct 5</span><span>Oct 12</span></div><p class="note">Supported contributions, not estimated carbon saved.</p></div><div class="panel field-notes"><h3>Keep the momentum.</h3><p class="muted">A small action you can repeat is a good place to start.</p>${linkBtn('Explore challenges','discover','full')}</div></aside></div>`}
function signin(){return `<div class="sign-in"><div class="welcome"><span class="eyebrow" style="color:var(--color-accent);">Welcome to Zyvara</span><h1>Your next good<br>thing starts here.</h1><p style="color:#EAF0E5;">Find your community. Document your effort.<br>Build a habit worth sharing.</p>${sprout()}</div><form id="signin-form" class="form"><div class="stack" style="gap:8px;"><h2>Make yourself at home.</h2><p class="muted">Sign in to create challenges and share your contributions.</p></div>${btn('Continue with Google','google-signin','secondary full')}<div class="auth-divider">or continue with email</div>${field('email','Email address','','We’ll send a secure sign-in link.','email')}<button type="submit" class="btn full">Send sign-in link ${icon('mail',20)}</button><p class="note">By continuing, you agree to Zyvara’s Terms and Privacy Policy. These links are placeholders in this design preview.</p><a href="#discover" class="small muted">Just exploring? Browse challenges →</a><p id="signin-message" role="status" class="small muted"></p></form></div>`}
function foundations(){return `<div class="system-heading"><div class="stack" style="gap:16px;"><span class="eyebrow">Field notes / Design system 1.0</span><h1>Small actions.<br>Shared momentum.</h1></div><p class="muted">A field journal for a greener world.<br>ZYVARA.US</p></div><section class="system-section"><h2>Palette / objects from the field</h2><div class="swatches">${[['Paper','canvas','#F7F8F2'],['Forest ink','ink','#172E25'],['Evergreen','primary','#245C42'],['Young leaf','accent','#DCEAA5'],['Slate','muted','#59675F'],['Field line','border','#DCE2D8']].map(([n,t,h])=>`<div class="swatch"><div class="swatch-box" style="background:var(--color-${t});"></div><strong>${n}</strong><span class="note">${h}</span></div>`).join('')}</div></section><section class="system-section"><div class="type-specimens"><div><span class="eyebrow">Manrope / Display</span><div class="display">Make your mark.</div><p class="muted">80/88 hero · 56/64 display · 40/48 page · 28/36 section<br>700–800 weight · −0.03 to −0.045em tracking</p></div><div><span class="eyebrow">Inter / Interface</span><p style="font-size:20px;line-height:28px;">Progress is a practice, not a perfect score.</p><p class="muted">16/24 body · 14/20 metadata · 600 control weight<br>Sentence case · Persistent labels · Plain language</p></div></div></section><section class="system-section"><h2>Space to grow</h2><div class="spacing-grid">${[4,8,12,16,24,32,48,64,80,96].map(n=>`<div class="spacing-sample"><i style="height:${n}px;"></i><span>${n}px</span></div>`).join('')}</div><p class="muted">4px base. Tight within groups; generous between sections. Corners: 8px controls, 16px cards, 24px feature surfaces.</p></section><section class="system-section"><div class="rule-grid">${[['01','Inviting, not guilt-driven','Specific, achievable actions. Warm language. Recognize effort without ranking personal worth.'],['02','Documented, not overstated','Display assessed contributions and points. Avoid unsupported CO₂, waste-weight, or verification claims.'],['03','Consistent, not repetitive','Shared tokens and components; use scale and spacing to vary emphasis. One strong color moment per screen.']].map(([n,h,p])=>`<div class="rule"><span class="rule-number">${n}</span><h3>${h}</h3><p class="muted">${p}</p></div>`).join('')}</div></section>`}
function components(){return `${header('The everyday toolkit.','Reusable controls, visible states, and enough room to breathe.')}<section class="system-section"><div class="eyebrow">01 / Actions / 48px default · 44px compact</div><div class="system-controls">${btn('Submit evidence '+icon('arrow',20),'demo-success')}${btn('Save draft','demo-success','secondary')}${btn('View challenge ↗','demo-success','ghost')}${btn('Remove photo','remove-photo','danger')}</div><div class="system-controls"><button class="btn" style="background:var(--color-primary-hover);">Hover</button><button class="btn" style="background:var(--color-primary-active);">Pressed</button><button class="btn" style="outline:2px solid var(--color-focus);outline-offset:3px;">Focus</button><button class="btn" aria-busy="true">${icon('clock',20)}Submitting…</button><button class="btn" disabled>Disabled</button></div></section><section class="system-section"><div class="eyebrow">02 / Forms / Persistent labels</div><div class="state-cards"><div class="field"><label class="label" for="default-input">Challenge title</label><input id="default-input" placeholder="Name a clear, specific action"><span class="helper">Default · Up to 80 characters</span></div><div class="field"><label class="label" for="focus-input">Challenge title</label><input id="focus-input" value="Clean up a local park" style="border:2px solid var(--color-focus);"><span class="helper">Focus · Visible keyboard outline</span></div><div class="field invalid"><label class="label" for="error-input">Challenge title</label><input id="error-input" aria-invalid="true" aria-describedby="error-hint"><span id="error-hint" class="helper">Add a title before publishing.</span></div></div><div class="form-two"><div class="field"><label for="demo-category" class="label">Category</label><select id="demo-category"><option>Cleanup</option><option>Planting</option><option>Recycling</option><option>Conservation</option></select></div>${textarea('demo-description','Describe your action','','What did you do? Give the community a little context.')}</div></section><section class="system-section"><div class="system-controls"><label class="check-row"><input type="checkbox"><span>I have permission to share these photos</span></label><label class="check-row"><input type="checkbox" checked><span>Share my contribution</span></label><label class="check-row"><input type="checkbox" role="switch" checked><span>Community notifications</span></label></div><div class="system-controls"><span class="badge">Cleanup</span><span class="badge">50 points</span><span class="badge">Ends in 3 days</span><div class="avatar">HA</div><span>Henry A.<br><span class="note">Community member</span></span></div></section><section class="system-section"><div class="eyebrow">03 / Navigation & iconography</div><div class="system-controls">${['leaf','users','plus','chart','camera','search','check','alert','shield','refresh','heart','comment'].map(n=>`<div class="stack" style="gap:8px;align-items:center;width:80px;">${icon(n,24)}<span class="note">${n}</span></div>`).join('')}</div><p class="note">24px icons · 1.7px strokes · 44px interactive targets · Icons are paired with labels when meaning is ambiguous.</p></section>`}
function feedback(){return `${header('Every state deserves care.','Clear outcomes, recoverable errors, and feedback that helps people continue.')}<section class="system-section"><h2>Assessment outcomes</h2><div class="state-cards">${Object.entries(outcomes).map(([k,o])=>`<div class="state-card">${status(o.kind,o.label)}<h3>${o.points?'+50 points':'0 points'}</h3><p class="muted">${k==='supported'?'The visible evidence aligns with the challenge.':k==='insufficient'?'A wider, clearer photo will help us assess the result.':'The visible evidence does not match the requested activity.'}</p>${btn(k==='supported'?'View progress':'Review evidence','preview-'+k,'secondary')}</div>`).join('')}</div></section><section class="system-section"><div class="state-cards"><div class="state-card">${status('info','Assessment in progress')}<h3>Looking at your evidence.</h3><p class="muted">Your submission is saved. You can return to this screen while assessment continues.</p><div class="skeleton big"></div><div class="skeleton" style="width:80%;"></div><div class="skeleton" style="width:55%;"></div>${btn('Preview result','preview-supported','secondary')}</div><div class="state-card">${status('error','Assessment unavailable')}<h3>Your effort is still saved.</h3><p class="muted">We couldn’t complete the assessment. Try again without re-uploading your photos.</p>${btn(icon('refresh',20)+'Retry assessment','retry')}</div><div class="state-card">${status('warning','Photo needs attention')}<h3>This photo is too large.</h3><p class="muted">Choose a JPG, PNG, or WebP photo smaller than 10 MB. Your description stays saved.</p>${btn('Choose another photo','open-evidence','secondary')}</div></div></section><section class="system-section"><h2>Empty & first-time states</h2><div class="form-two"><div class="empty-state">${icon('leaf',40)}<h3>Your journal starts with one action.</h3><p class="muted">Complete a challenge and document your effort. Your contributions will appear here.</p>${linkBtn('Explore challenges','discover')}</div><div class="empty-state">${icon('search',40)}<h3>No challenges found.</h3><p class="muted">Try another category or clear your search.</p>${btn('Reset filters','reset-filters','secondary')}</div></div></section><section class="system-section"><h2>Confirmations & notifications</h2><div class="system-controls">${btn('Preview remove-photo dialog','remove-photo','secondary')}${btn('Preview unsaved-changes dialog','leave-form','secondary')}${btn('Preview saved notification','demo-success','secondary')}${btn('Preview share confirmation','share','secondary')}</div><p class="note">Dialogs trap focus, return focus to the trigger, and close with Escape. Toasts supplement persistent status; they never carry essential errors alone.</p></section>`}
function rules(){return `${header('Built to keep growing.','The rules that turn a visual language into a reliable product.')}<section class="system-section"><h2>Responsive behavior</h2><div class="rule-grid">${[['01','Desktop / 1280–1440','64px page gutters. Three challenge columns. 48px content/rail gap. Forms stay readable at a maximum of 800px.'],['02','Tablet / 768–1024','24–40px gutters. Two challenge columns. Rails move below content. No horizontal overflow.'],['03','Mobile / 390','20px gutters. One column. 36/42 headlines. Uploads stack. Primary actions expand. Four-tab bottom navigation.']].map(([n,h,p])=>`<div class="rule"><span class="rule-number">${n}</span><h3>${h}</h3><p class="muted">${p}</p></div>`).join('')}</div></section><section class="system-section"><h2>Accessibility & behavior</h2><div class="rule-grid">${[['Keyboard first','Logical tab order. Visible 2px blue focus with 4px offset. Escape closes dialogs; focus returns to its trigger.'],['Contrast and meaning','16px body text. 14px metadata. Semantic states use icons and explicit text, in addition to color.'],['Respect attention','120–180ms transitions. Reduced-motion preference removes motion. Show saved status during loading or errors.'],['Evidence and privacy','One result photo required. Before photo optional. Size/type errors are inline. Community sharing defaults off.'],['Human-readable AI','Supported, needs evidence, and not supported are distinct outcomes. Avoid certainty percentages and “verified” badges.'],['Fair recognition','Award 50 points once for a supported contribution. No points for unclear or mismatched evidence. Keep recovery actionable.']].map(([h,p])=>`<div class="rule"><h3>${h}</h3><p class="muted">${p}</p></div>`).join('')}</div></section><section class="system-section references"><h2>Reference study / Dribbble</h2>${[['Waste Bank Community App','https://dribbble.com/shots/26853352-Waste-Bank-Community-App','Participation hierarchy and readable community metrics. Zyvara uses a quieter, editorial visual language.'],['E-Larder','https://dribbble.com/shots/27640793-E-Larder-Community-Food-Sharing-Food-Rescue-App','Practical local actions and social trust. Keep contribution context and privacy choices legible.'],['Sunrise Plant','https://dribbble.com/shots/26511262-Sunrise-Plant-Tree-Planting-Website-Design','Mission-led storytelling and clear calls to action. Adapt optimism and hierarchy into the application flow.']].map(([h,u,p])=>`<div class="reference-item"><div><a href="${u}" target="_blank" rel="noopener">${h} ↗</a></div><div><p class="muted">${p}</p></div></div>`).join('')}<p class="note">References inform principles. Zyvara’s mark, palette, layout, and vector illustrations are original to this design study.</p></section><section class="system-section"><h2>Handoff / system structure</h2><pre class="token-code">tokens.css        75 shared tokens, all 11 namespaces\nsystem.css        Layout, components, semantic states, responsive rules\nprototype.js      12 views and illustrative interaction states\nDESIGN-SYSTEM.md   Component contract, content rules, flow and limitations\n\nCore journey: Discover → Details → Evidence → Assessment → Progress\nCommunity journey: Create → Publish confirmation → Details → Community\n\nPaper: Foundations, Controls, Discover, Details, Create, Evidence\nRemaining native Paper layouts require restored connector access.</pre></section>`}
const views={discover,details,create,evidence,assessment,community,progress,signin,foundations,components,feedback,rules};
function render(){selector.value=state.screen;app.innerHTML=navigation()+`<main class="main" id="main">${views[state.screen]()}</main>`+bottomNavigation();stage.classList.toggle('is-mobile',state.mobile);document.getElementById('desktop').classList.toggle('selected',!state.mobile);document.getElementById('mobile').classList.toggle('selected',state.mobile);document.getElementById('desktop').setAttribute('aria-pressed',String(!state.mobile));document.getElementById('mobile').setAttribute('aria-pressed',String(state.mobile));bindForms()}
function route(name){if(!screens[name])name='discover';location.hash=name}
function toast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),3800)}
function dialog(title,copy,confirmLabel,callback,danger=false){const previous=document.activeElement;const overlay=document.getElementById('overlay');overlay.innerHTML=`<div class="dialog-backdrop"><section class="dialog" role="dialog" aria-modal="true" aria-labelledby="dialog-title" aria-describedby="dialog-description"><div class="row between"><h2 id="dialog-title">${title}</h2><button class="icon-button" id="dialog-close" aria-label="Close dialog">${icon('close',20)}</button></div><p id="dialog-description">${copy}</p><div class="dialog-actions"><button class="btn secondary" id="dialog-cancel">Keep editing</button><button class="btn ${danger?'danger':''}" id="dialog-confirm">${confirmLabel}</button></div></section></div>`;const close=()=>{overlay.innerHTML='';document.removeEventListener('keydown',onKey);if(previous?.isConnected)previous.focus()};const onKey=e=>{if(e.key==='Escape')close();if(e.key==='Tab'){const items=overlay.querySelectorAll('button');const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}};document.addEventListener('keydown',onKey);document.getElementById('dialog-close').onclick=close;document.getElementById('dialog-cancel').onclick=close;document.getElementById('dialog-confirm').onclick=()=>{close();callback()};document.getElementById('dialog-cancel').focus()}
function bindForms(){const createForm=document.getElementById('create-form');if(createForm)createForm.onsubmit=e=>{e.preventDefault();let invalid=null;for(const field of createForm.querySelectorAll('[required]')){const bad=!field.value.trim();field.closest('.field').classList.toggle('invalid',bad);field.setAttribute('aria-invalid',String(bad));if(bad&&!invalid)invalid=field;if(bad){const helper=field.closest('.field').querySelector('.helper');helper.textContent='Complete this field before publishing.'}}if(invalid){invalid.focus();return}dialog('Ready to invite your community?','Your challenge will show the title, requirements, category, and deadline you entered. This preview does not publish data.','Preview published challenge',()=>{route('details');toast('Challenge published — design preview only.')})};const desc=document.getElementById('submission-description');if(desc)desc.oninput=()=>{state.description=desc.value;document.getElementById('submit-evidence').disabled=!state.photos[0]||!desc.value.trim()};const share=document.getElementById('share-choice');if(share)share.onchange=()=>state.shared=share.checked;for(const input of document.querySelectorAll('[data-photo]')){input.onchange=()=>loadPhoto(input.files[0],Number(input.dataset.photo));const area=input.closest('.upload-area');area.ondragover=e=>{e.preventDefault();area.style.borderColor='var(--color-primary)'};area.ondragleave=()=>area.style.borderColor='';area.ondrop=e=>{e.preventDefault();area.style.borderColor='';loadPhoto(e.dataTransfer.files[0],Number(input.dataset.photo))}}const evidenceForm=document.getElementById('evidence-form');if(evidenceForm)evidenceForm.onsubmit=e=>{e.preventDefault();if(!state.photos[0]||!state.description.trim())return;state.assessment='supported';toast('Previewing an illustrative result; no AI request was sent.');route('assessment')};const signin=document.getElementById('signin-form');if(signin)signin.onsubmit=e=>{e.preventDefault();const email=document.getElementById('email');if(!email.checkValidity()||!email.value.trim()){email.reportValidity();return}document.getElementById('signin-message').textContent='Preview only: no sign-in link was sent. The production flow uses your authentication provider.'}}
function loadPhoto(file,i){if(!file)return;state.photoErrors[i]='';if(!['image/jpeg','image/png','image/webp'].includes(file.type))state.photoErrors[i]='Choose a JPG, PNG, or WebP photo.';else if(file.size>10*1024*1024)state.photoErrors[i]='This photo is too large. Choose one smaller than 10 MB.';else{if(state.photos[i])URL.revokeObjectURL(state.photos[i]);state.photos[i]=URL.createObjectURL(file)}render()}
app.addEventListener('click',e=>{const filter=e.target.closest('[data-category]');if(filter){state.category=filter.dataset.category;render();return}const outcome=e.target.closest('[data-outcome]');if(outcome){state.assessment=outcome.dataset.outcome;render();return}const like=e.target.closest('[data-like]');if(like){const i=Number(like.dataset.like);state.liked[i]=!state.liked[i];state.likes[i]+=state.liked[i]?1:-1;render();return}const comment=e.target.closest('[data-comment]');if(comment){const i=Number(comment.dataset.comment);const box=document.getElementById('comment-'+i);box.hidden=false;box.innerHTML=`<form class="comment-box" id="comment-form-${i}"><label class="sr-only" for="comment-input-${i}">Write an encouraging comment</label><input id="comment-input-${i}" placeholder="A little encouragement goes a long way" required maxlength="300"><button class="btn compact" type="submit">Post</button></form>`;const input=document.getElementById('comment-input-'+i);input.focus();document.getElementById('comment-form-'+i).onsubmit=ev=>{ev.preventDefault();if(!input.value.trim())return;state.comments.push({post:i,text:input.value.trim()});render();toast('Comment added to this local preview.')};return}const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;if(action.startsWith('preview-')){state.assessment=action.slice(8);route('assessment');return}switch(action){case'reset-filters':state.category='All actions';state.query='';if(state.screen==='discover')render();else route('discover');break;case'demo-success':toast('Your changes are saved — design preview.');break;case'retry':toast('Retrying the illustrative assessment…');setTimeout(()=>{state.assessment='supported';route('assessment')},800);break;case'open-evidence':route('evidence');break;case'google-signin':toast('Design preview: Google sign-in is not connected.');break;case'share':dialog('Share your contribution?','Your chosen photos, description, challenge, and assessment status will appear in the community. Review photos for personal details first. This preview does not upload or publish.','Share contribution',()=>{route('community');toast('Contribution shared — local preview only.')});break;case'remove-photo':dialog('Remove this photo?','You can add it again. Your description will remain saved.','Remove photo',()=>{if(state.photos[0])URL.revokeObjectURL(state.photos[0]);state.photos[0]=null;toast('Photo removed from this preview.')},true);break;case'leave-form':dialog('Leave without saving?','Your unsaved changes will be lost. You can keep editing instead.','Leave form',()=>route('discover'),true);break}});
app.addEventListener('input',e=>{if(e.target.id==='challenge-search'){state.query=e.target.value;document.getElementById('challenge-cards').innerHTML=filteredCards()}});
selector.onchange=()=>route(selector.value);
document.getElementById('desktop').onclick=()=>{state.mobile=false;render()};
document.getElementById('mobile').onclick=()=>{state.mobile=true;render()};
window.addEventListener('hashchange',()=>{state.screen=screens[location.hash.slice(1)]?location.hash.slice(1):'discover';render();window.scrollTo(0,0)});
state.screen=screens[location.hash.slice(1)]?location.hash.slice(1):'discover';render();
